export default function LoadingScreen() {
  const [phase, setPhase] = useState<"drawing" | "filled" | "fadeout" | "done">("drawing");

  useEffect(() => {
    const fillTimer  = setTimeout(() => setPhase("filled"),  3200);
    const fadeTimer  = setTimeout(() => setPhase("fadeout"), 4000);
    const doneTimer  = setTimeout(() => setPhase("done"),    4800);
    return () => { clearTimeout(fillTimer); clearTimeout(fadeTimer); clearTimeout(doneTimer); };
  }, []);

  if (phase === "done") return null;

  const isDrawing = phase === "drawing";

  return (
    <>
      <style>{`
        .loader-wrap {
          position: fixed; inset: 0; z-index: 9999;
          background: #f7f3ed;
          display: flex; align-items: center; justify-content: center;
          flex-direction: column; gap: 0.75rem;
          opacity: ${phase === "fadeout" ? "0" : "1"};
          transition: opacity 0.7s ease;
          pointer-events: ${phase === "fadeout" ? "none" : "all"};
        }
        .loader-svg {
          width: min(420px, 75vw);
          height: auto;
          overflow: visible;
          display: block;
          margin: 0 auto;
        }
        /* While drawing — stroke only, animating dashoffset */
        .sig-stroke {
          fill: none;
          stroke: #1a1714;
          stroke-linecap: round;
          stroke-linejoin: round;
          stroke-width: 18;
          stroke-dasharray: 18000;
          stroke-dashoffset: 18000;
          animation: drawSig 2.8s cubic-bezier(0.3, 0, 0.2, 1) 0.3s forwards;
        }
        /* Once done — filled solid, no stroke needed */
        .sig-filled {
          fill: #1a1714;
          stroke: none;
        }
        @keyframes drawSig {
          to { stroke-dashoffset: 0; }
        }
        .loader-line {
          width: 0; height: 1px; background: #c8a96e;
          animation: growLine 0.8s ease 3.0s forwards;
        }
        @keyframes growLine { to { width: min(240px, 44vw); } }
        .loader-name {
          font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
          font-size: 10px; font-weight: 600; letter-spacing: 0.38em;
          text-transform: uppercase; color: #6e6660; opacity: 0;
          animation: fadeInName 0.6s ease 3.1s forwards;
        }
        @keyframes fadeInName { to { opacity: 1; } }
      `}</style>

      <div className="loader-wrap">
        <svg
          className="loader-svg"
          viewBox="440 550 2600 1350"
          xmlns="http://www.w3.org/2000/svg"
        >
          <path
            className={isDrawing ? "sig-stroke" : "sig-filled"}
            d={SIG_PATH}
          />
        </svg>
        <div className="loader-line" />
        <p className="loader-name">Susan Herrmann Loomis</p>
      </div>
    </>
  );
}